&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les &#233;coles de magie&lt;a class=&quot;headeranchor&quot; id=&quot;Les_&#233;coles_de_magie_0&quot; href=&quot;#Les_&#233;coles_de_magie_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;&#201;coles-De-Magie.html&quot; title=&quot;Les &#233;coles de magie du magicien&quot;&gt;pr&#233;sentation&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Abjuration-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Abjuration&quot;&gt;Abjuration&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Air-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire de l&amp;#39;Air&quot;&gt;Air&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bois-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du Bois&quot;&gt;Bois&lt;/a&gt; (UM)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Divination-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole de Divination&quot;&gt;Divination&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Eau-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire de l&amp;#39;Eau&quot;&gt;Eau&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enchantement-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Enchantement&quot;&gt;Enchantement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vocation-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;&#201;vocation&quot;&gt;&#201;vocation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Feu-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du Feu&quot;&gt;Feu&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Illusion-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Illusion&quot;&gt;Illusion&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invocation-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Invocation&quot;&gt;Invocation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tal-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du M&#233;tal&quot;&gt;M&#233;tal&lt;/a&gt; (UM)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;N&#233;ant-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du N&#233;ant&quot;&gt;N&#233;ant&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;N&#233;cromancie-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole de N&#233;cromancie&quot;&gt;N&#233;cromancie&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Terre-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire de la Terre&quot;&gt;Terre&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Transmutation-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole de Transmutation&quot;&gt;Transmutation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cole-Universelle-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole Universelle&quot;&gt;&#201;cole universelle&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Plus d&#39;information sur les sorts de cette &#233;cole &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#ABJURATION&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;ici&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;i&gt;Les abjurateurs retournent la magie contre elle-m&#234;me et se sp&#233;cialisent dans les sorts qui prot&#232;gent ou bloquent les assaillants.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#233;sistance (Ext).&lt;/b&gt; L’abjurateur gagne une r&#233;sistance de 5 points &#224; un type d’&#233;nergie qu’il choisit lorsqu’il pr&#233;pare ses sorts et qui peut &#234;tre diff&#233;rente d’un jour &#224; l’autre. Au niveau 11, cette r&#233;sistance passe &#224; 10 points. Au niveau 20, elle se transforme en une immunit&#233; au type d’&#233;nergie choisi.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Champ de protection (Sur).&lt;/b&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, l’abjurateur peut cr&#233;er un champ de protection magique de 3 m (2 cases) de rayon. Ce champ est centr&#233; sur lui et persiste pendant un nombre de rounds &#233;gal &#224; son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;. Tous les alli&#233;s de l’abjurateur se trouvant dans ce champ (y compris l’abjurateur lui-m&#234;me) gagnent un bonus de parade de +1 &#224; leur &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; . Ce bonus s’accro&#238;t de +1 par tranche de cinq niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;. Chaque jour, l’abjurateur peut utiliser ce pouvoir un nombre de fois &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Absorption d’&#233;nergie (Sur).&lt;/b&gt; Au niveau 6, l’abjurateur acquiert la capacit&#233; d’absorber chaque jour une certaine quantit&#233; d’&#233;nergie &#233;gale &#224; trois fois son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;. Chaque fois qu’il subit des d&#233;g&#226;ts d’&#233;nergie, son immunit&#233;, sa vuln&#233;rabilit&#233; ou sa r&#233;sistance &#233;ventuelles s’appliquent en premier lieu puis le reste des d&#233;g&#226;ts est d&#233;duit de son total d’absorption quotidien. Si tous les d&#233;g&#226;ts ne peuvent pas &#234;tre absorb&#233;s, ceux en exc&#232;s s’appliquent normalement &#224; l’abjurateur.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Champs d&#39;&#233;tude magiques&lt;a class=&quot;headeranchor&quot; id=&quot;Champs_d&#233;tude_magiques_0&quot; href=&quot;#Champs_d&#233;tude_magiques_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Les &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magiciens&lt;/a&gt; qui se sp&#233;cialisent dans une &#233;cole de magie peuvent choisir de restreindre davantage encore leur domaine d’&#233;tude. Les &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magiciens&lt;/a&gt; qui choisissent un champ d’&#233;tude magique conservent les sorts en bonus de leur &#233;cole de sp&#233;cialisation et doivent toujours s&#233;lectionner deux &#233;coles oppos&#233;es mais certains de leurs pouvoirs d’&#233;cole de magie sont modifi&#233;s ou remplac&#233;s. Ils doivent accepter toutes les modifications impos&#233;es par leur champ d’&#233;tude. Une fois un champ d’&#233;tude choisi, cette d&#233;cision ne peut plus &#234;tre modifi&#233;e.&lt;br /&gt;&lt;br /&gt;&lt;table class=&quot;page espace-col deuxcol&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;div class=&quot;presentation arrondi&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt; Bannissement &lt;a class=&quot;headeranchor&quot; id=&quot;Bannissement_1&quot; href=&quot;#Bannissement_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;b&gt;Pouvoirs remplac&#233;s.&lt;/b&gt; Les pouvoirs d’&#233;cole suivants remplacent &lt;i&gt;Champ de protection&lt;/i&gt; et &lt;i&gt;Absorption d’&#233;nergie&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Liens instables (Sur).&lt;/b&gt; Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 1, d’un simple toucher, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut d&#233;faire les liens qui retiennent une cr&#233;ature convoqu&#233;e (ou appel&#233;e) au plan o&#249; elle a &#233;t&#233; invoqu&#233;e. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquesdecontact.html&quot; title=&quot;attaque de contact au corps &#224; corps&quot;&gt;attaque de contact au corps &#224; corps&lt;/a&gt;, il peut rendre une cr&#233;ature convoqu&#233;e (ou appel&#233;e) &#224; la fois &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secou&#233;e&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Chancelant.html&quot; title=&quot;Chancelant&quot;&gt;chancelante&lt;/a&gt; pendant un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; &#233;gal &#224; la moiti&#233; de son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; (au minimum 1 round). Il peut utiliser cette capacit&#233; un nombre de fois par jour &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Aura de bannissement (Sur).&lt;/b&gt; Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 8, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut &#233;mettre une aura de bannissement de 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) de rayon pendant un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour &#233;gal &#224; son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; (ces &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; ne doivent pas forc&#233;ment &#234;tre cons&#233;cutifs). Toutes les cr&#233;atures convoqu&#233;es (ou appel&#233;es) au sein de l’aura doivent r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; pour ne pas &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Chancelant.html&quot; title=&quot;Chancelant&quot;&gt;chancelantes&lt;/a&gt;. En cas d’&#233;chec, elles restent &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Chancelant.html&quot; title=&quot;Chancelant&quot;&gt;chancelantes&lt;/a&gt; jusqu’&#224; ce qu’elles quittent la zone de l’aura. Les cr&#233;atures qui ratent un second jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; sont imm&#233;diatement renvoy&#233;es vers leur plan d’origine et le sort qui les a invoqu&#233;es prend fin imm&#233;diatement. Si ce sort a invoqu&#233; plus d’une cr&#233;ature, seule celle qui a rat&#233; son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; est affect&#233;e.
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;
&lt;div class=&quot;presentation arrondi&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt; Contresort &lt;a class=&quot;headeranchor&quot; id=&quot;Contresort_2&quot; href=&quot;#Contresort_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;b&gt;Pouvoirs remplac&#233;s.&lt;/b&gt; Les pouvoirs d’&#233;cole suivants remplacent &lt;i&gt;Champ de protection&lt;/i&gt; et &lt;i&gt;Absorption d’&#233;nergie&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Perturbation (Sur).&lt;/b&gt; Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 1, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut perturber une incantation d’un simple toucher. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquesdecontact.html&quot; title=&quot;attaque de contact au corps &#224; corps&quot;&gt;attaque de contact au corps &#224; corps&lt;/a&gt;, il peut placer un champ perturbateur autour de la cible. Tant que ce champ reste en place, la cible doit effectuer un test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; pour lancer un sort ou utiliser une capacit&#233; (ce test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; vient en plus des autres tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; &#233;ventuellement n&#233;cessaires). Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de ce test est &#233;gal &#224; 15 + deux fois le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; du sort. En cas d’&#233;chec, le sort est perdu. Le champ perturbateur reste en place pendant un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; &#233;gal &#224; la moiti&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; du magicien (minimum 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;). Le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut utiliser cette capacit&#233; un nombre de fois par jour &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Ma&#238;trise du contresort (Sur).&lt;/b&gt; Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 6, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; re&#231;oit &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Contresort.html&quot; title=&quot;Science du contresort&quot;&gt;Science du contresort&lt;/a&gt; en tant que don suppl&#233;mentaire. Une fois par jour, il peut tenter de contrer le sort d’un adversaire par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt; (au lieu d’une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Modifiant-Linitiative#Preparer.html&quot; title=&quot;Action pr&#233;par&#233;e&quot;&gt;action pr&#233;par&#233;e&lt;/a&gt;). Il doit utiliser un sort appartenant &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Niveau.html&quot; title=&quot;Niveau de sort&quot;&gt;niveau&lt;/a&gt; strictement sup&#233;rieur &#224; celui du sort contr&#233; pour tirer parti de cette capacit&#233;. Il peut utiliser cette capacit&#233; une fois par jour au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 6, plus une fois de plus par jour tous les quatre &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveaux&lt;/a&gt; par la suite.
&lt;/div&gt;
&lt;/table&gt;
